<?php
require_once __DIR__.'/../../../app/app.php';PageGuard::capability(Capabilities::SALES_RECORD);
$H=new Models\HeldOrderModel(Database::pdo());$isStaff=TenantContext::role()==='staff';$base=public_url(($isStaff?'staff':'super').'/restaurant/');
if($_SERVER['REQUEST_METHOD']==='POST'){$H->discard((int)($_POST['id']??0));$_SESSION['flash']['success']='Held restaurant order discarded.';header('Location: '.$base.'held.php');exit;}
$holds=$H->listWithItemsForTenant('restaurant');$page_title='Held Restaurant Orders';ob_start();?>
<div class="d-flex justify-content-between align-items-start flex-wrap gap-2 mb-4"><div><h1 class="h5 fw-bold mb-1">Held restaurant orders</h1><p class="small text-muted mb-0">Restaurant holds are separate from shop and credit-sale holds.</p></div><a class="btn btn-primary btn-sm" href="<?php echo $base;?>new.php">New order</a></div>
<div class="row g-3"><?php if(!$holds):?><div class="col-12"><div class="card border-0 shadow-sm"><div class="card-body text-center text-muted py-5">No held restaurant orders.</div></div></div><?php else:foreach($holds as $h):?><div class="col-md-6 col-xl-4"><div class="card border-0 shadow-sm h-100"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h6 fw-bold"><?php echo htmlspecialchars($h['customer_name']?:'Unnamed order');?></h2><span class="badge bg-light text-dark"><?php echo (int)$h['item_count'];?> items</span></div><small class="text-muted"><?php echo htmlspecialchars($h['created_at']);?></small><ul class="small mt-3 mb-3"><?php foreach(array_slice($h['items'],0,5) as $item):?><li><?php echo number_format((float)$item['quantity'],2);?> × <?php echo htmlspecialchars($item['product_name']);?></li><?php endforeach;?></ul><div class="fw-semibold mb-3">KES <?php echo number_format((float)$h['total'],2);?></div><div class="d-flex gap-2"><a class="btn btn-primary btn-sm flex-grow-1" href="<?php echo $base;?>new.php?resume=<?php echo (int)$h['id'];?>">Resume</a><form method="post" onsubmit="return confirm('Discard this held order?')"><input type="hidden" name="id" value="<?php echo (int)$h['id'];?>"><button class="btn btn-outline-danger btn-sm">Discard</button></form></div></div></div></div><?php endforeach;endif;?></div>
<?php $content=ob_get_clean();$__layout=$isStaff?'staff':'tenants';include __DIR__.'/../../templates/'.$__layout.'/layout.php';
